// shell = the handler: a registry of view-model factories + one host for the active view
class ShellViewModel : INotifyPropertyChanged {
    readonly Dictionary<string, Func<object>> factories = new() { ["chart"] = () => new ChartVm(model) };
    object current;
    public object CurrentViewModel { get => current; private set { current = value; OnPropertyChanged(); } }
    public void Open(string type) => CurrentViewModel = factories[type]();   // create + switch
}
// XAML: <ContentControl Content="{Binding CurrentViewModel}"/> + a DataTemplate per view-model type
